        <section v-if="transaction.phase !== 'idle'" class="transaction-card" :class="`transaction-${transaction.phase}`" aria-live="polite">
          <div class="transaction-heading"><div class="transaction-heading-copy"><span class="section-kicker">{{ transaction.label }}</span><h3>{{ transactionHeadline }}</h3><p>{{ transactionMessage }}</p></div><div class="transaction-elapsed" v-if="transaction.startedAt"><span>Elapsed</span><strong>{{ elapsedLabel }}</strong></div></div>
          <ol class="transaction-timeline" aria-label="GenLayer transaction lifecycle">
            <li v-for="(step, index) in transactionSteps" :key="step" :class="{ complete: index < transactionStage, current: index === transactionStage && transaction.phase !== 'success' && transaction.phase !== 'failure', failed: transaction.phase === 'failure' && index === transactionStage }"><span class="timeline-marker"><CircleCheck v-if="index < transactionStage || transaction.phase === 'success'" :size="13" /><span v-else>{{ index + 1 }}</span></span><span><strong>{{ step }}</strong><small v-if="index === transactionStage && transaction.phase !== 'success' && transaction.phase !== 'failure'">{{ transaction.phase === "pending" ? "Still in progress" : "Current step" }}</small></span></li>
          </ol>
          <div class="transaction-footer"><div class="hash-block"><span>Transaction hash</span><code v-if="transaction.hash">{{ transaction.hash }}</code><span v-else>Waiting for wallet response</span></div><div class="transaction-actions"><button v-if="transaction.hash" class="button button-outline" :disabled="loading" @click="refresh"><RefreshCw :class="{ spinning: loading }" :size="14" /> Check status</button><button class="text-button" @click="transaction.phase === 'pending' ? null : dismissTransaction()">{{ transaction.phase === "pending" ? "Leave this page safely" : "Dismiss" }}</button></div></div>
        </section>

        <div v-if="recovery.length" class="recovery-card">
          <span class="recovery-icon"><Clock3 :size="17" /></span><div class="recovery-copy"><span class="section-kicker">Transaction recovery</span><h3 v-if="recovery[0]?.hash">Tracking the original transaction</h3><h3 v-else>Review the previous request</h3><p v-if="recovery[0]?.hash">NimbusPact will reconcile the saved hash and will never submit a duplicate automatically.</p><p v-else>No transaction ID was returned. Confirm the wallet did not approve a request before releasing this local retry lock.</p></div><button v-if="recovery[0]?.hash" class="button button-outline" :disabled="loading" @click="refresh"><RefreshCw :size="14" /> Check status</button><button v-else class="button button-outline" :disabled="loading" @click="releaseRecovery(recovery[0])">Release retry lock</button>
        </div>

        <div class="coverage-toolbar"><div class="filter-tabs" role="tablist" aria-label="Filter covers"><button v-for="filter in coverageFilters" :key="filter.key" role="tab" :aria-selected="dashboardFilter === filter.key" :class="{ active: dashboardFilter === filter.key }" @click="dashboardFilter = filter.key">{{ filter.label }} <span>{{ filter.count }}</span></button></div><button class="text-button" :disabled="loading" @click="refresh"><RefreshCw :class="{ spinning: loading }" :size="14" /> {{ loading ? "Refreshing" : "Refresh state" }}</button></div>

        <div v-if="!policies.length && !loading" class="empty-state"><span class="empty-icon"><CloudSun :size="26" /></span><span class="section-kicker">A clear start</span><h3>No covers yet</h3><p>Choose a weather condition and fund your first exact-payout cover.</p><button class="button button-dark" @click="openCreateFlow">Create cover <ArrowRight :size="15" /></button></div>
        <div v-else-if="!filteredPolicies.length" class="empty-filter-state"><p>No covers match this view.</p><button class="text-button" @click="dashboardFilter = 'all'">Show all covers</button></div>
        <div v-else class="policy-grid">
          <article v-for="policy in filteredPolicies" :key="policy.policy_id" class="policy-card" :class="{ selected: selectedPolicy?.policy_id === policy.policy_id }" tabindex="0" role="button" @click="selectPolicy(policy)" @keydown.enter="selectPolicy(policy)" @keydown.space.prevent="selectPolicy(policy)">
            <div class="policy-card-top"><span class="policy-id">{{ policy.policy_id }}</span><span class="status-tag" :class="statusClass(policy.status)">{{ statusLabel(policy.status) }}</span></div>
            <div class="policy-card-main"><div><h3>{{ policy.location_name }}</h3><p>{{ triggerLabel(policy.trigger_type) }} <span aria-hidden="true">&middot;</span> {{ dateLabel(policy.start_date) }} - {{ dateLabel(policy.end_date) }}</p></div><strong>{{ formatGen(policy.payout_amount) }} <small>GEN</small></strong></div>
            <div class="policy-rule"><span>{{ metricUnit(policy.metric) }}</span><strong>&ge; {{ policy.threshold }}</strong></div>
            <div class="policy-card-bottom"><span class="policy-beneficiary"><UserRound :size="13" /> {{ shortAddress(policy.beneficiary) }}</span><div class="policy-actions"><button v-if="policy.status === 'ACTIVE'" class="inline-button" :disabled="busy || !resolutionWindowClosed(policy)" :title="resolutionWindowClosed(policy) ? 'Resolve cover' : 'Observation is still in progress'" @click.stop="resolve(policy)"><Radar :size="13" /> {{ resolutionWindowClosed(policy) ? "Resolve" : "Observation in progress" }}</button><button v-else-if="policy.status === 'DATA_UNAVAILABLE' && canRetry(policy)" class="inline-button" :disabled="busy" @click.stop="resolve(policy)"><RefreshCw :size="13" /> Retry verification</button><button v-else-if="policy.status === 'TRIGGERED' && !policy.withdrawn" class="inline-button inline-button-dark" :disabled="busy" @click.stop="claim(policy)"><HandCoins :size="13" /> Claim payout</button><button v-if="canRefund(policy)" class="inline-button inline-button-refund" :disabled="busy" @click.stop="refund(policy)"><HandCoins :size="13" /> Claim refund</button></div></div>
            <p v-if="policy.status === 'ACTIVE'" class="policy-timing">Observation closes {{ formatUtcTimestamp(observationCloseTimestamp(policy)) }}.</p><p v-else-if="policy.status === 'DATA_UNAVAILABLE' && refundAvailableTimestamp(policy)" class="policy-timing">Refund available after {{ formatUtcTimestamp(refundAvailableTimestamp(policy) || 0) }}.</p>
          </article>
