      <section v-if="selectedPolicy" class="detail-panel section-width" aria-live="polite">
        <div class="detail-header"><div><span class="section-kicker">Cover detail</span><h2>{{ selectedPolicy.location_name }} <span class="muted-id">{{ selectedPolicy.policy_id }}</span></h2></div><div class="detail-header-actions"><span class="status-tag" :class="statusClass(selectedPolicy.status)">{{ statusLabel(selectedPolicy.status) }}</span><button class="icon-button" aria-label="Close cover detail" @click="selectedPolicy = null">&times;</button></div></div>
        <div class="detail-layout"><div class="detail-main">
